/**
 * How trustworthy a number on an Admin screen is. Used by the dashboards to
 * label what they show, so seeded or invented figures are never read as
 * measurements.
 *
 * - `live`: measured from a real, connected source. NOTHING in this
 *   prototype qualifies yet: there is no analytics integration and the
 *   learner activity store is not aggregated here. The label exists so a
 *   real source can use it, and is covered by a test that nothing claims it.
 * - `demo`: a fixed seeded dataset, or counts taken over one.
 * - `simulated`: generated by a formula or scaled to look like activity.
 * - `unavailable`: the source does not exist; nothing is shown as a value.
 */

export type DataSourceKind = 'live' | 'demo' | 'simulated' | 'unavailable'

export const DATA_SOURCE_LABEL: Record<DataSourceKind, string> = {
  live: 'Live',
  demo: 'Demo data',
  simulated: 'Simulated',
  unavailable: 'Unavailable',
}

export const DATA_SOURCE_DESCRIPTION: Record<DataSourceKind, string> = {
  live: 'Measured from a connected source.',
  demo: 'Seeded sample data for prototype review. Not measured activity.',
  simulated: 'Generated by a formula to illustrate the screen. Not measured activity.',
  unavailable: 'No data source is connected for this yet.',
}
